<?php

declare(strict_types=1);

namespace Tests\Unit;

use PHPUnit\Framework\TestCase;

/**
 * G7 ratchet gate. The old stylesheets (app.css, ald1n-ui-v2.css, ald1n-liquid-glass.css, ald1n-ui-refinement.css,
 * ald1n-dashboard-d1.css, vendor/liquid-glass-web.css) are still linked from layouts.app, layouts.guest and
 * errors.minimal. Before they can be deleted, no view or script may rely on a class that only they define.
 *
 *  - tests/Fixtures/removed-css-classes.json is generated by scripts/legacy-css-classes.mjs and frozen.
 *  - VIEW_ALLOWLIST holds the views that still use such classes today. A new view or script using one fails; a view
 *    that no longer does must be removed from the list (the list can only shrink).
 *  - VAR_ALLOWLIST does the same for var(--primary|--line|--bg|--panel|--ald-*|--lg5-*|--lg2-*).
 *
 * Known limit: classes assembled at runtime ("status-{{ $x }}") are not seen, only literal tokens.
 * Author: Ald1n <https://ald1n.com>
 */
final class LegacyCssClassesContractTest extends TestCase
{
    /** Views (relative to resources/views, no extension) that still use a removed class. Shrink only. */
    private const VIEW_ALLOWLIST = [
    ];

    /** Files (relative to the CMS root) that still use an old custom property. Shrink only. */
    private const VAR_ALLOWLIST = [];

    private const VAR_PATTERN = '/var\(\s*--(?:primary|line|bg|panel|ald-[\w-]+|lg5-[\w-]+|lg2-[\w-]+)\b/';

    private static function root(): string
    {
        return dirname(__DIR__, 2);
    }

    /** @return array<string, string> relative path => source, Blade views except public-shop plus public JS */
    private static function sources(): array
    {
        $root = self::root();
        $out = [];
        $views = $root.'/resources/views';
        $it = new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($views, \FilesystemIterator::SKIP_DOTS));
        foreach ($it as $file) {
            $rel = str_replace('\\', '/', substr($file->getPathname(), strlen($root) + 1));
            if (str_ends_with($rel, '.blade.php') && ! str_starts_with($rel, 'resources/views/public-shop/')) {
                $out[$rel] = (string) file_get_contents($file->getPathname());
            }
        }
        foreach (glob($root.'/public/assets/js/*.js') ?: [] as $js) {
            $out['public/assets/js/'.basename($js)] = (string) file_get_contents($js);
        }
        ksort($out);

        return $out;
    }

    /** @return list<string> class tokens a source file refers to */
    private static function classesIn(string $source): array
    {
        $tokens = [];
        $add = static function (string $text) use (&$tokens): void {
            $text = preg_replace('/\$[A-Za-z_]\w*(?:->\w+|\[[^\]]*\])*/', ' ', $text) ?? $text;
            foreach (preg_split('/[^A-Za-z0-9_-]+/', $text, -1, PREG_SPLIT_NO_EMPTY) ?: [] as $t) {
                $tokens[$t] = true;
            }
        };

        // class="..." / class='...' (Blade expressions inside are scanned as plain text, string literals included)
        if (preg_match_all('/\bclass\s*=\s*"([^"]*)"|\bclass\s*=\s*\'([^\']*)\'/i', $source, $m)) {
            foreach (array_merge($m[1], $m[2]) as $v) {
                $add($v);
            }
        }
        // @class([ 'a b' => cond, 'c' ])
        if (preg_match_all('/@class\(\s*\[(.*?)\]\s*\)/s', $source, $m)) {
            foreach ($m[1] as $body) {
                if (preg_match_all('/([\'"])([^\'"]+)\1/', $body, $s)) {
                    foreach ($s[2] as $v) {
                        $add($v);
                    }
                }
            }
        }
        // classList.add('a', 'b') / remove / toggle / contains / replace, className = '...'
        if (preg_match_all('/classList\.(?:add|remove|toggle|contains|replace)\(([^)]*)\)|className\s*[+]?=\s*([\'"][^\'"]*[\'"])/', $source, $m)) {
            foreach (array_merge($m[1], $m[2]) as $args) {
                if (preg_match_all('/([\'"`])([^\'"`]+)\1/', $args, $s)) {
                    foreach ($s[2] as $v) {
                        $add($v);
                    }
                }
            }
        }
        // querySelector('.a .b'), querySelectorAll, closest, matches, getElementsByClassName
        if (preg_match_all('/(?:querySelector(?:All)?|closest|matches)\(\s*([\'"`])([^\'"`]*)\1/', $source, $m)) {
            foreach ($m[2] as $sel) {
                $sel = preg_replace('/\[[^\]]*\]/', '', $sel) ?? $sel;
                if (preg_match_all('/\.(-?[_a-zA-Z][\w-]*)/', $sel, $c)) {
                    foreach ($c[1] as $v) {
                        $tokens[$v] = true;
                    }
                }
            }
        }
        if (preg_match_all('/getElementsByClassName\(\s*([\'"])([^\'"]+)\1/', $source, $m)) {
            foreach ($m[2] as $v) {
                $add($v);
            }
        }

        return array_keys($tokens);
    }

    /** @return array<string, true> */
    private static function forbidden(): array
    {
        $data = json_decode((string) file_get_contents(self::root().'/tests/Fixtures/removed-css-classes.json'), true, 512, JSON_THROW_ON_ERROR);

        return array_fill_keys($data['classes'], true);
    }

    /** @param array<string, string> $sources @return array<string, list<string>> view => forbidden classes found */
    private static function violations(array $sources, array $forbidden): array
    {
        $found = [];
        foreach ($sources as $path => $source) {
            $hits = array_values(array_filter(self::classesIn($source), static fn (string $c): bool => isset($forbidden[$c])));
            if ($hits !== []) {
                sort($hits);
                $found[$path] = $hits;
            }
        }

        return $found;
    }

    private static function key(string $path): string
    {
        return preg_replace('#^resources/views/|\.blade\.php$#', '', $path) ?? $path;
    }

    public function test_the_frozen_list_is_not_empty(): void
    {
        self::assertGreaterThan(500, count(self::forbidden()), 'removed-css-classes.json is empty or truncated.');
    }

    public function test_no_new_view_or_script_uses_a_removed_class(): void
    {
        $found = self::violations(self::sources(), self::forbidden());
        $keys = [];
        foreach ($found as $path => $hits) {
            $keys[self::key($path)] = $hits;
        }
        $new = array_diff_key($keys, array_flip(self::VIEW_ALLOWLIST));

        self::assertSame([], array_map(static fn (array $h): string => implode(' ', array_slice($h, 0, 6)), $new),
            'These files use classes that only the old stylesheets define. Use a1-* components, do not extend the allowlist.');
    }

    public function test_the_allowlist_only_shrinks(): void
    {
        $found = self::violations(self::sources(), self::forbidden());
        $keys = array_map(self::key(...), array_keys($found));
        $stale = array_values(array_diff(self::VIEW_ALLOWLIST, $keys));

        self::assertSame([], $stale, 'These allowlisted views no longer use a removed class: delete them from VIEW_ALLOWLIST.');
    }

    public function test_a_synthetic_view_with_an_old_class_is_caught(): void
    {
        $forbidden = self::forbidden();
        foreach (['<div class="panel">', '<div @class([\'panel\' => true])>', "<script>el.classList.add('panel')</script>", "<script>document.querySelector('.panel')</script>"] as $sample) {
            self::assertNotSame([], self::violations(['x' => $sample], $forbidden), $sample.' must be reported.');
        }
        self::assertSame([], self::violations(['x' => '<div class="a1-card">'], $forbidden), 'a1-* must pass.');
    }

    public function test_no_new_use_of_old_custom_properties(): void
    {
        $found = [];
        foreach (self::sources() as $path => $source) {
            if (preg_match(self::VAR_PATTERN, $source)) {
                $found[] = $path;
            }
        }

        self::assertSame([], array_values(array_diff($found, self::VAR_ALLOWLIST)),
            'These files use var(--primary|--line|--bg|--panel|--ald-*|--lg5-*|--lg2-*); use the Kobalt tokens.');
        self::assertSame([], array_values(array_diff(self::VAR_ALLOWLIST, $found)),
            'These allowlisted files no longer use an old custom property: delete them from VAR_ALLOWLIST.');
    }

    public function test_the_shell_layouts_link_only_stylesheets_that_exist(): void
    {
        $root = self::root();
        foreach (['layouts/app', 'layouts/guest', 'errors/minimal'] as $view) {
            $source = (string) file_get_contents($root.'/resources/views/'.$view.'.blade.php');
            self::assertSame(1, preg_match_all("#asset\\('(assets/[^']+\\.(?:css|js))'\\)#", $source, $m) > 0 ? 1 : 0, $view.' links no assets.');
            foreach (array_unique($m[1]) as $asset) {
                self::assertFileExists($root.'/public/'.$asset, $view.' links a missing file: '.$asset);
            }
        }
    }
}
